    uiTxLen    : UINT;
    uiRxLen    : UINT;
    xWrReq     : BOOL;          // REQ cho chu kỳ sau (state machine quyết định)
    xRdReq     : BOOL;
    xWrDone    : BOOL;
    xWrBusy    : BOOL;
    xWrErr     : BOOL;
